// Сохранение сессии роли после теста. Refresh-токен Supabase одноразовый: приложение при загрузке обновляет токен,
// и старый .qa/auth/<role>.json становится недействительным. Поэтому в конце каждого теста (в finally)
// записываем свежий storageState обратно — следующий тест/прогон войдёт уже с ним.
import type { Page } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

export async function saveSession(page: Page, role: string) {
  if (role === 'guest' || page.isClosed()) return;
  try {
    const state = await page.context().storageState();
    // Не затирать рабочую сессию пустой (например, если приложение вышло из аккаунта).
    const ok = state.origins.some((o) => o.localStorage.some((kv) => /auth-token/.test(kv.name) && kv.value.includes('refresh_token')));
    if (!ok) return;
    const file = path.resolve(__dirname, '../../../auth', `${role}.json`);
    fs.writeFileSync(file, JSON.stringify(state, null, 2));
  } catch {
    // сохранение сессии не должно скрывать результат теста
  }
}
